INSERT INTO public.blog_humor_material (id, excerpt, source_url, source_title, source_kind, topics, mechanism, analysis, adaptation, quality, enabled, version, created_at, updated_at) VALUES
('literal-lunch-label', '午餐肉', 'https://blog.ifuyun.com/post/00lq2zu9e7riqwir', '2023年弱智吧经典问题（1~100）', 'REPRINT', ARRAY['吃饭', '食物', '名字', '时间', '生活']::TEXT[], 'LITERAL', '把食品名称中的时段误认成使用限制，认真询问错了前提。', '这是早餐店，所以我下午来买包子，应该算访问了历史页面。', 4, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('literal-pool-idiom', '池中之物', 'https://static.tieba.baidu.com/p/10354221105?pn=13', '弱智吧2025年度365佳贴', 'PRIMARY_POST', ARRAY['成语', '语言', '水池', '水族馆', '孩子']::TEXT[], 'LITERAL', '把形容人的成语放回真实水池，赞许变成了场景辨认。', '他说项目已经上岸，我找遍仓库，连一条救生绳都没有。', 5, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('literal-earphone-department', '蓝牙耳机', 'https://tieba.baidu.com/hottopic/browse/hottopic?topic_id=24632759&topic_name=%E5%BC%B1%E6%99%BA%E5%90%A7%E5%A4%A7%E6%88%98%E4%BA%BA%E5%B7%A5%E6%99%BA%E8%83%BD', '弱智吧大战人工智能', 'PRIMARY_LISTING', ARRAY['耳机', '设备', '故障', '名称', '技术', '修理']::TEXT[], 'LITERAL', '把设备名里的身体部位当成真实器官，让维修问题走进错误科室。', '听说用了无头浏览器，我赶紧把网页上的帽子广告撤了。', 4, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('literal-cola-adjective', '可口可乐', 'https://linux.do/t/topic/122808', '2024年上半年 弱智吧 精选', 'REPRINT', ARRAY['饮料', '品牌', '形容词', '命名', '食物']::TEXT[], 'LITERAL', '把商标读成普通形容词组合，评价口味反而改变了产品身份。', '这款软件真的很好用，我宣布它正式获得实用工具这个名字。', 4, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('literal-scooter-joy', '老头乐坏了', 'https://blog.ifuyun.com/post/00m0j7wb24og8lke', '2024年弱智吧经典问题（51-120）', 'REPRINT', ARRAY['老人', '车辆', '情绪', '断句', '歧义', '修理']::TEXT[], 'LITERAL', '改变断句后，同一串字分别指高兴过头和代步车故障。', '客服说服务员在更新，我开始担心他什么时候会重启。', 5, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('literal-team-building-pass', '不过去了', 'https://blog.ifuyun.com/post/00mdql3fbbif3gdy', '2025年弱智吧经典问题（64~104）', 'REPRINT', ARRAY['团建', '职场', '拒绝', '歧义', '说话', '社交']::TEXT[], 'LITERAL', '从惯用语中拆出空间动作，用一句短回应避开施压。', '同事说今天必须拿出态度，我翻了翻抽屉，态度还没采购。', 4, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('literal-forum-particle', '你好，我是弱智吧', 'https://gitextract.com/Leymore/ruozhiba', 'Full Code of Leymore/ruozhiba for AI', 'REPRINT', ARRAY['介绍', '名字', '语气词', '歧义', '社区', '对话']::TEXT[], 'LITERAL', '把名称的末字读成不确定语气，身份介绍突然变成自我猜测。', '群友介绍自己叫大概。我觉得他连自我介绍都留了误差。', 4, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('causal-meteor-destination', '陨石坑', 'https://blog.ifuyun.com/post/00lq2zu9e7riqwir', '2023年弱智吧经典问题（1~100）', 'REPRINT', ARRAY['陨石', '宇宙', '地理', '原因', '结果', '巧合']::TEXT[], 'CAUSAL_REVERSAL', '把撞击产生的坑当成预先存在的目的地，结果被倒置成原因。', '报错总在出故障的地方出现，日志的选址眼光确实稳定。', 5, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('causal-bus-disappearance', '路边就会有人消失', 'https://blog.ifuyun.com/post/00lqkrtmficv3nf5', '2023年弱智吧经典问题（101~148）', 'REPRINT', ARRAY['公交', '交通', '观察', '消失', '场景', '因果']::TEXT[], 'CAUSAL_REVERSAL', '省略乘客上车这个中间环节，正常过程被观察成神秘事件。', '每次点击发布，草稿就少一篇。我怀疑按钮在偷偷吃文章。', 4, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('causal-subtitle-direction', '照着字幕说话', 'https://blog.ifuyun.com/post/00m0j7wb24og8lke', '2024年弱智吧经典问题（51-120）', 'REPRINT', ARRAY['视频', '字幕', '内容', '配音', '顺序', '创作']::TEXT[], 'CAUSAL_REVERSAL', '把记录台词的字幕当成控制台词的指令，颠倒制作顺序。', '导航每次都知道我拐向哪儿，看来方向盘一直在听它安排。', 4, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('causal-courier-time', '提前3天发', 'https://tieba.baidu.com/hottopic/browse/hottopic?topic_id=24632759&topic_name=%E5%BC%B1%E6%99%BA%E5%90%A7%E5%A4%A7%E6%88%98%E4%BA%BA%E5%B7%A5%E6%99%BA%E8%83%BD', '弱智吧大战人工智能', 'PRIMARY_LISTING', ARRAY['快递', '等待', '时间', '提前', '效率', '流程']::TEXT[], 'CAUSAL_REVERSAL', '为消除等待，把动作移到需求产生之前，漏掉先知道需求的条件。', '为避免上线后改需求，我们可以提前写好用户撤回需求的感谢信。', 5, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('causal-final-rank', '让亚军去打冠军', 'https://blog.ifuyun.com/post/00mdql3fbbif3gdy', '2025年弱智吧经典问题（64~104）', 'REPRINT', ARRAY['比赛', '排名', '输赢', '结果', '顺序', '评选']::TEXT[], 'CAUSAL_REVERSAL', '拿比赛之后确定的身份解释比赛之前的安排，胜负像已被预定。', '落选稿总输给获奖稿，建议下次先把文件名改成一等奖。', 5, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('causal-remove-night', '为什么还要有晚上', 'https://tieba.baidu.com/p/7717657283', '既然熬夜有害，那么为什么还要有晚上呢', 'PRIMARY_POST', ARRAY['夜晚', '作息', '时间', '环境', '推理', '生活']::TEXT[], 'CAUSAL_REVERSAL', '把行为发生的环境当成问题的责任方，取消背景被当成解决方法。', '需求总在开会后增加，建议先把会议室改成储物间。', 4, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('causal-parents-wedding', '没邀请我参加婚礼', 'https://blog.ifuyun.com/post/00lq2zu9e7riqwir', '2023年弱智吧经典问题（1~100）', 'REPRINT', ARRAY['父母', '婚礼', '出生', '时间', '家庭', '邀请']::TEXT[], 'CAUSAL_REVERSAL', '把后来出生的人放进更早的事件，现实时间线被社交礼节替代。', '开工仪式没邀请成品参加，难怪它后来一直不愿意按时出现。', 4, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('concept-water-pythagoras', '勾股定理', 'https://static.tieba.baidu.com/p/10354221105?pn=13', '弱智吧2025年度365佳贴', 'PRIMARY_POST', ARRAY['数学', '勾股', '容量', '水杯', '单位', '推理']::TEXT[], 'CONCEPT_MISMATCH', '保留熟悉的数字关系，却把适用于边长的定理错用到水量。', '页面只剩三个按钮，按三角形稳定性，架构已经通过民间评审。', 5, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('concept-child-driving-ticket', '儿童考驾照可以半价吗', 'https://tieba.baidu.com/p/9139134580', 'AI大战弱智吧！入院or出院你来定', 'PRIMARY_POST', ARRAY['儿童', '身高', '驾照', '票价', '规则', '资格']::TEXT[], 'CONCEPT_MISMATCH', '把景点按身高优惠的规则迁移到驾驶资格，收费和准入被混为一谈。', '账号等级只有一半，服务器能不能也只向我收半次超时？', 4, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('concept-cpp-score-increment', 'C++程序设计是60分', 'https://blog.ifuyun.com/post/00lwphglb3iqbsl3', '2024年弱智吧经典问题（1-50）', 'REPRINT', ARRAY['编程', 'C语言', '考试', '分数', '自增', '学习']::TEXT[], 'CONCEPT_MISMATCH', '把语言名称里的运算符当成成绩运算，让代码语义越界到考试。', '周报从草稿变成草稿++，按我院算法，工作量已经增加了一。', 5, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('concept-donut-decentralized', '去中心化的面包', 'https://blog.ifuyun.com/post/00m5ca9wl4jdpwy8', '2024年弱智吧经典问题（121-168）', 'REPRINT', ARRAY['甜甜圈', '面包', '结构', '中心', '技术', '架构']::TEXT[], 'CONCEPT_MISMATCH', '把技术领域的组织结构术语按几何外形应用到食物，严肃词落地。', '这张空白计划表没有任何核心任务，去中心化做得相当彻底。', 5, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('concept-truth-buoyancy', '真相浮出水面', 'https://kyle.ai/blog/7624.html', '2021 年弱智吧上半年精选', 'REPRINT', ARRAY['真相', '浮力', '物理', '密度', '比喻', '信息']::TEXT[], 'CONCEPT_MISMATCH', '把表示揭晓的比喻当成浮力实验，从语言图像推出物理属性。', '项目进度沉下去了，我怀疑本周需求的密度超过了人力。', 5, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('concept-binary-silicon', '他们都是硅基生物', 'https://gitextract.com/Leymore/ruozhiba', 'Full Code of Leymore/ruozhiba for AI', 'REPRINT', ARRAY['二极管', '电子', '思维', '硅', '分类', '互联网']::TEXT[], 'CONCEPT_MISMATCH', '把思维方式的电子元件比喻当成材料证据，跨域推导身份。', '会议里每个人都在放电，可见办公楼已经具备独立供能能力。', 4, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('concept-wages-zero-sum', '谁在亏钱', 'https://tieba.baidu.com/hottopic/browse/hottopic?topic_id=24632759&topic_name=%E5%BC%B1%E6%99%BA%E5%90%A7%E5%A4%A7%E6%88%98%E4%BA%BA%E5%B7%A5%E6%99%BA%E8%83%BD', '弱智吧大战人工智能', 'PRIMARY_LISTING', ARRAY['赚钱', '工作', '经济', '零和', '收入', '价值']::TEXT[], 'CONCEPT_MISMATCH', '把劳动收入简化成零和输赢，忽略生产价值，朴素疑问暴露模型缺口。', '大家都说要节省时间，我想知道被省下来的时间目前由谁保管。', 4, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('daily-rebel-office-font', '仿宋_GB2312', 'https://blog.ifuyun.com/post/00lqkrtmficv3nf5', '2023年弱智吧经典问题（101~148）', 'REPRINT', ARRAY['职场', '字体', '离职', '叛逆', '习惯', '文档']::TEXT[], 'DAILY_LIFE', '宏大的叛逆动作被熟悉的公文习惯收尾，人物越认真反差越大。', '我决定辞职去追求自由，辞职信先按公司模板排了三个版本。', 5, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('daily-hidden-benefits', '隐藏福利藏得真深', 'https://blog.ifuyun.com/post/00lwphglb3iqbsl3', '2024年弱智吧经典问题（1-50）', 'REPRINT', ARRAY['工作', '公司', '福利', '等待', '职场', '自嘲']::TEXT[], 'DAILY_LIFE', '用宣传说辞替长期没有兑现找借口，真诚口吻反衬现实落差。', '项目说会给我成就感，可能采用了异步投递，我还在等回调。', 5, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('daily-procrastination-learning', '今天就先不学了', 'https://blog.ifuyun.com/post/00mbr2dxoreqtbpu', '2025年弱智吧经典问题（1~63）', 'REPRINT', ARRAY['拖延', '学习', '计划', '今天', '明天', '习惯']::TEXT[], 'DAILY_LIFE', '谈学习拖延时当场做出拖延动作，让观点被说话行为证实。', '看完自动化教程，我把明天开始设成了每日自动提醒。执行暂时手动。', 5, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('daily-wallet-freedom', '这何尝不是一种财富自由', 'https://blog.ifuyun.com/post/00ml2hwvesw2nyq8', '弱智吧21周年合辑', 'REPRINT', ARRAY['钱包', '钱', '理想', '自由', '预算', '自嘲']::TEXT[], 'DAILY_LIFE', '把成功词汇重新解释成钱脱离自己的处境，用积极措辞承认窘迫。', '我的预算已经实现弹性伸缩：东西一贵，购物车就自动缩小。', 4, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('daily-boss-quest-npc', '他是不是NPC啊', 'https://www.3dmgame.com/original/3743485.html', '弱智吧，弱智只占三分之二', 'REPRINT', ARRAY['老板', '任务', '工作', '游戏', '重复', '职场']::TEXT[], 'DAILY_LIFE', '拿游戏任务发放者解释重复的职场动作，日常疲惫获得轻巧出口。', '老板的支线任务每天刷新，就是经验条一直没动，可能我漏领了奖励。', 5, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('daily-office-fishing', '公司的水太深', 'https://linux.do/t/topic/283578', '周五了，来盖个楼吧！（弱智吧名言讨论）', 'REPRINT', ARRAY['职场', '摸鱼', '公司', '水', '比喻', '工作']::TEXT[], 'DAILY_LIFE', '把职场隐喻接成真实水域，为日常偷闲制造一本正经的环境解释。', '会议把任务分得很细，我负责认真观察它们怎样逐渐超过下班时间。', 4, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('daily-shift-ratio', '上一休二', 'https://tieba.baidu.com/mo/q/f?ie=utf-8&jump_tieba_native=1&kw=%E5%BC%B1%E6%99%BA', '弱智吧_百度贴吧', 'PRIMARY_LISTING', ARRAY['上班', '休息', '时间', '工时', '比例', '生活']::TEXT[], 'DAILY_LIFE', '把每天的小时比例改叫轮班天数，用计算包装过于乐观的休息感。', '我只点一次开始，进度条却忙了十分钟，按工时看它才是项目主力。', 4, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('person-grass-anxiety', '草会有容貌焦虑吗', 'https://blog.ifuyun.com/post/00mbr2dxoreqtbpu', '2025年弱智吧经典问题（1~63）', 'REPRINT', ARRAY['草', '花', '植物', '评价', '容貌', '情绪']::TEXT[], 'PERSONIFICATION', '把人的外貌比较和被忽略的感受交给普通植物，熟悉景色换了视角。', '首页的配图收到了很多夸奖，页脚小字把自己又缩小了一号。', 5, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('person-door-defense', '不关我的事', 'https://blog.ifuyun.com/post/00m5ca9wl4jdpwy8', '2024年弱智吧经典问题（121-168）', 'REPRINT', ARRAY['门', '家', '责任', '开关', '歧义', '解释']::TEXT[], 'PERSONIFICATION', '让门像人一样推卸责任，同时把开关动作藏进辩解的双关里。', '备份盘沉默了一晚上，它说自己只是备用，不该承担主角的情绪。', 5, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('person-lamp-sunrise', '开关是灯的日出日落', 'https://kyle.ai/blog/7624.html', '2021 年弱智吧上半年精选', 'REPRINT', ARRAY['灯', '开关', '太阳', '昼夜', '房间', '时间']::TEXT[], 'PERSONIFICATION', '从灯的尺度看昼夜，日常开关获得了属于物件的生活时间。', '路灯白天收起光，像是把晚上要说的话先攒在肚子里。', 5, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('person-moon-frown', '把不满写在脸上', 'https://www.sohu.com/a/895174512_122418614', '弱智吧：网络世界里的独特“净土”', 'REPRINT', ARRAY['月亮', '月牙', '天空', '表情', '情绪', '形状']::TEXT[], 'PERSONIFICATION', '用月相的缺口表现人的情绪，不完整的形状突然像一张有态度的脸。', '草稿箱没发过脾气，只是每次打开，都拿一排未完成看着我。', 4, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('person-paper-plane-calculation', '抖落了一身的演算', 'https://c.tieba.baidu.com/home/main?fr=home&id=tb.1.95ed1cb5.59LwkkSsIXKRv8-c1HcFXw', '用草纸叠了一只飞机（公开账户帖子列表）', 'PRIMARY_LISTING', ARRAY['纸飞机', '草稿', '数学', '书写', '飞行', '窗台']::TEXT[], 'PERSONIFICATION', '把草纸上的计算当成飞机的负担，让纸的用途变成物件的生活经历。', '那张写满待办的纸终于折成小船，替我把这个星期先划走了一点。', 5, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('person-bridge-comfort', '让河流不再难过', 'https://www.bilibili.com/video/BV1wx4y1n7gq/', '所有的桥都是温暖的，因为他让河流不再难过。', 'REPRINT', ARRAY['桥', '河流', '交通', '安慰', '歧义', '空间']::TEXT[], 'PERSONIFICATION', '把通过困难和情绪难受叠在一起，桥的通行作用被读成温柔安慰。', '键盘响得很热闹，每个键都急着替没说出口的话签个到。', 4, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('person-cloud-trend', '云就是喜欢跟风', 'https://blog.ifuyun.com/post/00mdql3fbbif3gdy', '2025年弱智吧经典问题（64~104）', 'REPRINT', ARRAY['云', '风', '天气', '潮流', '移动', '天空']::TEXT[], 'PERSONIFICATION', '把天气运动解释成追逐潮流的性格，双关替物件补上人类动机。', '光标在空白里不停闪烁，它比我更急着把这篇文章开个头。', 5, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
